// Um worker executa os jobs no ritmo dele e tenta de novo se falhar.
// Vocabulário: job (o trabalho), produtor (quem enfileira),
// worker (quem executa), concorrência, retry, dead letter.

import { EventEmitter } from 'node:events';

export interface Job<T> {
  readonly id: number;
  readonly name: string;
  readonly data: T; // o payload: cada fila define o seu
  attempts: number;
  status: 'waiting' | 'active' | 'completed' | 'failed';
  lastError?: string;
}

export type Processor<T, R> = (job: Job<T>) => Promise<R>;

// Mapa "nome do evento → argumentos do listener"
export interface QueueEvents<T, R> {
  completed: [job: Job<T>, result: R];
  retrying: [job: Job<T>, error: Error, delayMs: number];
  failed: [job: Job<T>, error: Error];
  drained: [];
}

export class MemoryQueue<T, R = void> extends EventEmitter<QueueEvents<T, R>> {
  // ... implementação nas próximas seções
}

// Uso: MemoryQueue<dados do job, resultado do processor>
const fila = new MemoryQueue<{ to: string }, string>(enviarEmail, { concurrency: 2 });

fila.on('completed', (job, messageId) => console.log(job.data.to, messageId)); // tipos inferidos
// fila.on('complete', ...)  // ❌ Erro: esse evento não existe

// Dentro de MemoryQueue<T, R>
readonly #waiting: Job<T>[] = [];
#active = 0;

add(name: string, data: T): Job<T> {
  const job: Job<T> = { id: this.#nextId++, name, data, attempts: 0, status: 'waiting' };
  this.#waiting.push(job);
  this.#pump(); // tenta começar agora
  return job;   // o produtor não espera o processamento
}

#pump(): void {
  while (this.#active < this.#concurrency) {
    const job = this.#waiting.shift(); // FIFO: o primeiro que entrou sai primeiro
    if (!job) return;
    void this.#run(job); // sem await: vários jobs rodando juntos
  }
}

async #run(job: Job<T>): Promise<void> {
  this.#active++;
  job.status = 'active';
  job.attempts++;

  // União discriminada: checar `ok` diz ao TS qual dos lados você tem
  let outcome: { ok: true; result: R } | { ok: false; error: Error };
  try {
    outcome = { ok: true, result: await this.#processor(job) };
  } catch (err) {
    // Em JS dá para lançar qualquer coisa: normalize para Error
    outcome = { ok: false, error: err instanceof Error ? err : new Error(String(err)) };
  }
  this.#active--;

  if (outcome.ok) {
    job.status = 'completed';
    this.emit('completed', job, outcome.result);
  } else {
    this.#handleFailure(job, outcome.error);
  }

  this.#pump(); // abriu uma vaga: puxa o próximo
}

#handleFailure(job: Job<T>, error: Error): void {
  job.lastError = error.message;

  if (job.attempts >= this.#maxAttempts) {
    job.status = 'failed';
    this.#deadLetter.push(job); // guarda para análise
    this.emit('failed', job, error);
    return;
  }

  // 100ms, 200ms, 400ms... dá tempo de o serviço externo se recuperar
  const delayMs = this.#backoffMs * 2 ** (job.attempts - 1);
  job.status = 'waiting';
  this.#scheduledRetries++;
  this.emit('retrying', job, error, delayMs);

  setTimeout(() => {
    this.#scheduledRetries--;
    this.#waiting.push(job);
    this.#pump();
  }, delayMs);
}

// Saída real com { concurrency: 2, maxAttempts: 3, backoffMs: 100 }:
// ↻ job 3 falhou (timeout no SMTP); nova tentativa em 100ms
// ↻ job 3 falhou (timeout no SMTP); nova tentativa em 200ms
// ✔ job 3 enviado → msg-3
// ✖ job 5 foi para a dead letter após 3 tentativas: endereço inválido

// Um tipo de erro que significa "não adianta tentar de novo"
export class PermanentError extends Error {}

// Na fila: erro permanente vai direto para a dead letter
#handleFailure(job: Job<T>, error: Error): void {
  job.lastError = error.message;
  const semRetry = error instanceof PermanentError;

  if (semRetry || job.attempts >= this.#maxAttempts) {
    job.status = 'failed';
    this.#deadLetter.push(job);
    this.emit('failed', job, error);
    return;
  }
  // ... backoff como antes
}

// No processor: quem conhece o domínio decide o que é permanente
async function enviarEmail(job: Job<EmailJob>): Promise<string> {
  if (!job.data.to.includes('@')) throw new PermanentError('endereço inválido');
  return smtp.send(job.data); // timeout aqui continua com retry
}

